import json, glob, re, collections, sys, os
BASE = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory'
R = {}
for f in sorted(glob.glob(BASE + '/raw/*.json')):
    for r in json.load(open(f)):
        r['_f'] = os.path.basename(f)[:-5]
        R[r['id']] = r


def fmt(r):
    s = f"[{r['id']}|{r.get('area')}] {r.get('name')} :: {r.get('what','')}"
    if r.get('ui'):
        s += f"\n   UI: {r['ui']}"
    if r.get('shortcuts'):
        s += f" SC:{r['shortcuts']}"
    if r.get('mcp'):
        s += f"\n   MCP: {r['mcp']}"
    if r.get('requires'):
        s += f" REQ:{r['requires']}"
    if r.get('details'):
        s += f"\n   D: {r['details']}"
    if r.get('evidence'):
        s += f"\n   E: {r['evidence']}"
    return s


KW = re.compile(r"\b(grade|grades|grading|graded|ungraded|lut|luts|\.cube|cube|look|looks|scope|scopes|vectorscope|waveform|parade|histogram|qualifier|qualifiers|wheels?|lift|gamma|gain|curves?|hue|saturation|exposure|adjustment|show selection|vibrance|temperature|tint|color tab|colour)\b", re.I)

if __name__ == '__main__':
    cmd = sys.argv[1]
    if cmd == 'stats':
        print(collections.Counter(r['_f'] for r in R.values() if r.get('area') == 'color'))
        print(len(R))
        n = [r for r in R.values() if r.get('area') != 'color' and KW.search(json.dumps({k: r.get(k) for k in ('name', 'what', 'ui', 'mcp', 'details')}))]
        print(len(n))
        print(collections.Counter(r.get('area') for r in n))
        print(collections.Counter(r['_f'] for r in n))
    elif cmd == 'file':
        for r in R.values():
            if r['_f'] == sys.argv[2] and (len(sys.argv) < 4 or r.get('area') == sys.argv[3]):
                print(fmt(r))
    elif cmd == 'colorother':
        for r in R.values():
            if r.get('area') == 'color' and r['_f'] not in ('guide-color-grading', 'code-color'):
                print(fmt(r))
    elif cmd == 'kwnames':
        for r in R.values():
            if r.get('area') != 'color' and KW.search(json.dumps({k: r.get(k) for k in ('name', 'what', 'ui', 'mcp', 'details')})):
                print(f"[{r['id']}|{r.get('area')}] {r.get('name')} :: {r.get('what','')[:140]}")

